// WebhookInitiator sends OpenAPI 3.1 webhook requests to target URLs.
// Modeled on the generated Client, but with no stored Server -- the full
// target URL is provided per-call by the caller (typically discovered
// from a subscription registration).
type WebhookInitiator struct {
	// Doer for performing requests, typically a *http.Client with any
	// customized settings, such as certificate chains.
	Client HttpRequestDoer

	// A list of callbacks for modifying requests which are generated before sending over
	// the network.
	RequestEditors []RequestEditorFn
}

// WebhookInitiatorOption allows setting custom parameters during construction.
type WebhookInitiatorOption func(*WebhookInitiator) error

// NewWebhookInitiator creates a new WebhookInitiator with reasonable defaults.
func NewWebhookInitiator(opts ...WebhookInitiatorOption) (*WebhookInitiator, error) {
	initiator := WebhookInitiator{}
	for _, o := range opts {
		if err := o(&initiator); err != nil {
			return nil, err
		}
	}
	if initiator.Client == nil {
		initiator.Client = &http.Client{}
	}
	return &initiator, nil
}

// WithWebhookHTTPClient allows overriding the default Doer, which is
// automatically created using http.Client. This is useful for tests.
func WithWebhookHTTPClient(doer HttpRequestDoer) WebhookInitiatorOption {
	return func(p *WebhookInitiator) error {
		p.Client = doer
		return nil
	}
}

// WithWebhookRequestEditorFn allows setting up a callback function, which
// will be called right before sending the webhook request. This can be
// used to mutate the request, e.g. to add signature headers.
func WithWebhookRequestEditorFn(fn RequestEditorFn) WebhookInitiatorOption {
	return func(p *WebhookInitiator) error {
		p.RequestEditors = append(p.RequestEditors, fn)
		return nil
	}
}

func (p *WebhookInitiator) applyWebhookEditors(ctx context.Context, req *http.Request, additionalEditors []RequestEditorFn) error {
	for _, r := range p.RequestEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	for _, r := range additionalEditors {
		if err := r(ctx, req); err != nil {
			return err
		}
	}
	return nil
}

// WebhookInitiatorInterface is the interface specification for the webhook initiator.
type WebhookInitiatorInterface interface {
	// FlowRunEndedWithBody fires the flows.run.ended.v1 webhook with any body
	FlowRunEndedWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error)

	FlowRunEnded(ctx context.Context, targetURL string, body FlowRunEndedJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error)
}

func (p *WebhookInitiator) FlowRunEndedWithBody(ctx context.Context, targetURL string, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewFlowRunEndedWebhookRequestWithBody(targetURL, contentType, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := p.applyWebhookEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return p.Client.Do(req)
}

func (p *WebhookInitiator) FlowRunEnded(ctx context.Context, targetURL string, body FlowRunEndedJSONRequestBody, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewFlowRunEndedWebhookRequest(targetURL, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := p.applyWebhookEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return p.Client.Do(req)
}

// NewFlowRunEndedWebhookRequest builds a application/json POST request for the flows.run.ended.v1 webhook
func NewFlowRunEndedWebhookRequest(targetURL string, body FlowRunEndedJSONRequestBody) (*http.Request, error) {
	var bodyReader io.Reader
	buf, err := json.Marshal(body)
	if err != nil {
		return nil, err
	}
	bodyReader = bytes.NewReader(buf)
	return NewFlowRunEndedWebhookRequestWithBody(targetURL, "application/json", bodyReader)
}

// NewFlowRunEndedWebhookRequestWithBody builds a POST request for the flows.run.ended.v1 webhook with any body
func NewFlowRunEndedWebhookRequestWithBody(targetURL string, contentType string, body io.Reader) (*http.Request, error) {
	var err error
	_ = err

	reqURL, err := url.Parse(targetURL)
	if err != nil {
		return nil, err
	}

	req, err := http.NewRequest(http.MethodPost, reqURL.String(), body)
	if err != nil {
		return nil, err
	}

	req.Header.Add("Content-Type", contentType)

	return req, nil
}
